# Model 2 of the 3D non-matching coupled Poisson example (tetrahedra):
# [0.5,1.0] x [0,1] x [0,1], 2 x 2 x 2 cubes, generated by cubemesh.
# Included by pdeapp.jl, which loads Exasim.
pde[2], mesh[2] = Exasim.initializeexasim();

pde[2].model = "ModelD";
pde[2].modelfile = "pdemodel2";    # module defined in pdemodel2.jl
include(joinpath(@__DIR__, "pdemodel2.jl"));
pde[2].modelnumber = 2;
pde[2].Cxxpreprocessing = 1;
pde[2].mpiprocs = 1;
pde[2].hybrid = 1;
pde[2].porder = 2;
pde[2].pgauss = 4;
pde[2].physicsparam = reshape([1.0], 1, 1);
pde[2].tau = [1.0];
pde[2].NLiter = 4;
pde[2].NLtol = 1e-12;
pde[2].linearsolvertol = 1e-12;
pde[2].matvectol = 1e-12;
pde[2].GMRESrestart = 250;
pde[2].linearsolveriter = 600;
pde[2].interfacetype = 1;

mesh[2].p, mesh[2].t = Exasim.Mesh.cubemesh(2, 2, 2, 0);
mesh[2].p[1, :] = 0.5 .+ 0.5 .* mesh[2].p[1, :];   # map x to [0.5,1]
# Boundaries: y = 0, x = 1, y = 1, x = 0.5, z = 0, z = 1
mesh[2].boundaryexpr = [p -> abs.(p[2,:]) .< 1e-8, p -> abs.(p[1,:] .- 1) .< 1e-8,
    p -> abs.(p[2,:] .- 1) .< 1e-8, p -> abs.(p[1,:] .- 0.5) .< 1e-8,
    p -> abs.(p[3,:]) .< 1e-8, p -> abs.(p[3,:] .- 1) .< 1e-8];
mesh[2].boundarycondition = [1 1 1 2 1 1];
mesh[2].interfacecondition = [0 0 0 1 0 0];   # boundary 4 is the coupled interface
pde[2].interfacefluxmap = [1];
